# Yōkai e chefes do Diário do Guardião. Ordem: pt_BR, en, es, de, fr, ru, id, ja, ko, zh_TW, zh_CN.
STRINGS = {
    "enemy.slime_rice.name": ["Slime-de-Arroz", "Rice Slime", "Limo de Arroz", "Reisschleim", "Gelée de riz", "Рисовый слизень", "Lendir Nasi", "米スライム", "쌀 슬라임", "米史萊姆", "米史莱姆"],
    "enemy.slime_rice.lore": ["Arroz oferecido aos mortos e esquecido no altar. Ainda tem fome de ser lembrado.", "Rice offered to the dead and forgotten on the altar. It still hungers to be remembered.", "Arroz ofrecido a los muertos y olvidado en el altar. Aún tiene hambre de ser recordado.", "Reis, den Toten geopfert und auf dem Altar vergessen. Er hungert noch danach, erinnert zu werden.", "Du riz offert aux morts et oublié sur l'autel. Il a encore faim qu'on se souvienne de lui.", "Рис, поднесённый мёртвым и забытый на алтаре. Он всё ещё жаждет, чтобы его помнили.", "Nasi persembahan untuk orang mati yang terlupa di altar. Masih lapar untuk diingat.", "死者に供えられ、祭壇で忘れられた米。今も思い出されることに飢えている。", "죽은 이에게 바쳐졌다 제단에 잊힌 쌀. 아직도 기억되기를 갈망한다.", "供奉亡者卻被遺忘在祭壇的米。仍渴望被人記起。", "供奉亡者却被遗忘在祭坛的米。仍渴望被人记起。"],
    "enemy.bat_lantern.name": ["Morcego-Lanterna", "Lantern Bat", "Murciélago Linterna", "Laternenfledermaus", "Chauve-souris lanterne", "Фонарная летучая мышь", "Kelelawar Lentera", "提灯コウモリ", "등불 박쥐", "燈籠蝙蝠", "灯笼蝙蝠"],
    "enemy.bat_lantern.lore": ["Viveram séculos nos beirais do templo, bebendo a luz das lanternas. Agora querem a sua.", "They lived for centuries under the temple eaves, drinking lantern light. Now they want yours.", "Vivieron siglos en los aleros del templo, bebiendo la luz de las linternas. Ahora quieren la tuya.", "Jahrhundertelang tranken sie unter dem Tempeldach Laternenlicht. Jetzt wollen sie deins.", "Ils ont vécu des siècles sous les avant-toits du temple, buvant la lumière des lanternes. Ils veulent la tienne.", "Веками они жили под стрехами храма, выпивая свет фонарей. Теперь им нужен твой.", "Berabad-abad mereka tinggal di atap kuil, meminum cahaya lentera. Kini mereka mau milikmu.", "何百年も寺の軒下で灯籠の光を吸ってきた。今はお前の光が欲しい。", "수백 년간 사원 처마 밑에서 등불 빛을 마셨다. 이제 네 빛을 원한다.", "牠們在寺院屋簷下吸食燈光數百年，如今想要你的光。", "它们在寺院屋檐下吸食灯光数百年，如今想要你的光。"],
    "enemy.skeleton_peasant.name": ["Camponês Esquecido", "Forgotten Peasant", "Campesino Olvidado", "Vergessener Bauer", "Paysan oublié", "Забытый крестьянин", "Petani Terlupa", "忘れられた農民", "잊힌 농민", "被遺忘的農民", "被遗忘的农民"],
    "enemy.skeleton_peasant.lore": ["Morreu na colheita sem que ninguém fizesse seu funeral. Ainda carrega a enxada.", "He died at harvest with no one to hold his funeral. He still carries his hoe.", "Murió en la cosecha sin que nadie le hiciera un funeral. Aún lleva la azada.", "Er starb bei der Ernte, niemand hielt ihm ein Begräbnis. Er trägt noch seine Hacke.", "Mort pendant la moisson, sans funérailles. Il porte encore sa houe.", "Он умер во время жатвы, и никто его не похоронил. До сих пор носит мотыгу.", "Ia mati saat panen tanpa ada yang memakamkannya. Masih membawa cangkulnya.", "収穫の最中に死に、弔う者もいなかった。今も鍬を手にしている。", "추수 중 죽었지만 장례를 치러 준 이가 없었다. 아직도 괭이를 들고 있다.", "他死於收割時，無人為他送葬。至今仍握著鋤頭。", "他死于收割时，无人为他送葬。至今仍握着锄头。"],
    "enemy.kappa_young.name": ["Kappa Jovem", "Young Kappa", "Kappa Joven", "Junger Kappa", "Jeune kappa", "Юный каппа", "Kappa Muda", "若い河童", "어린 갓파", "年輕河童", "年轻河童"],
    "enemy.kappa_young.lore": ["Mergulha dos arrozais em linha reta. Dizem que se curva a quem se curva primeiro.", "It dives out of the rice paddies in a straight line. They say it bows to whoever bows first.", "Se lanza desde los arrozales en línea recta. Dicen que se inclina ante quien se inclina primero.", "Er schießt geradeaus aus den Reisfeldern. Man sagt, er verbeugt sich vor dem, der sich zuerst verbeugt.", "Il jaillit des rizières en ligne droite. On dit qu'il salue qui le salue en premier.", "Выпрыгивает из рисовых полей по прямой. Говорят, кланяется тому, кто поклонится первым.", "Ia melesat lurus dari sawah. Konon ia membungkuk pada yang membungkuk lebih dulu.", "田んぼからまっすぐ飛び出してくる。先にお辞儀をした者には礼を返すという。", "논에서 일직선으로 튀어나온다. 먼저 절하는 자에게 절한다고 한다.", "從稻田直線衝出。據說牠會向先鞠躬的人回禮。", "从稻田直线冲出。据说它会向先鞠躬的人回礼。"],
    "enemy.shade_ghost.name": ["Fantasma Sombra", "Shade Ghost", "Fantasma Sombra", "Schattengeist", "Fantôme d'ombre", "Призрак-тень", "Hantu Bayangan", "影の亡霊", "그림자 유령", "影之幽靈", "影之幽灵"],
    "enemy.shade_ghost.lore": ["Viajantes que saíram da luz para ver a procissão de perto. Ainda estão olhando.", "Travelers who left the light to see the procession up close. They are still watching.", "Viajeros que salieron de la luz para ver la procesión de cerca. Siguen mirando.", "Reisende, die das Licht verließen, um die Prozession aus der Nähe zu sehen. Sie schauen noch immer.", "Des voyageurs sortis de la lumière pour voir la procession de près. Ils regardent encore.", "Путники, вышедшие из света, чтобы посмотреть на шествие вблизи. Они всё ещё смотрят.", "Pengelana yang keluar dari cahaya untuk melihat arak-arakan dari dekat. Mereka masih menatap.", "行列を近くで見ようと光の外へ出た旅人たち。今も見つめ続けている。", "행렬을 가까이서 보려고 빛 밖으로 나간 나그네들. 아직도 바라보고 있다.", "為近看百鬼而離開光芒的旅人。他們仍在凝視。", "为近看百鬼而离开光芒的旅人。他们仍在凝视。"],
    "enemy.tsuchigumo.name": ["Tsuchigumo", "Tsuchigumo", "Tsuchigumo", "Tsuchigumo", "Tsuchigumo", "Цутигумо", "Tsuchigumo", "土蜘蛛", "츠치구모", "土蜘蛛", "土蜘蛛"],
    "enemy.tsuchigumo.lore": ["A aranha da terra. Quando cai, seus filhotes continuam a caçada.", "The earth spider. When it falls, its young carry on the hunt.", "La araña de la tierra. Cuando cae, sus crías siguen la caza.", "Die Erdspinne. Fällt sie, jagen ihre Jungen weiter.", "L'araignée de terre. Quand elle tombe, ses petits poursuivent la chasse.", "Земляной паук. Когда он падает, охоту продолжают его детёныши.", "Laba-laba tanah. Saat ia tumbang, anak-anaknya melanjutkan perburuan.", "大地の蜘蛛。倒れても子らが狩りを続ける。", "땅거미. 쓰러지면 새끼들이 사냥을 잇는다.", "大地之蛛。牠倒下後，幼蛛會繼續狩獵。", "大地之蛛。它倒下后，幼蛛会继续狩猎。"],
    "enemy.slime_red.name": ["Slime de Brasa", "Ember Slime", "Limo de Brasa", "Glutschleim", "Gelée de braise", "Угольный слизень", "Lendir Bara", "燠火スライム", "불씨 슬라임", "餘燼史萊姆", "余烬史莱姆"],
    "enemy.slime_red.lore": ["Restos de um incenso que queimou rancor em vez de preces.", "The remains of incense that burned grudges instead of prayers.", "Restos de un incienso que quemó rencor en lugar de plegarias.", "Reste von Räucherwerk, das Groll statt Gebete verbrannte.", "Les restes d'un encens qui a brûlé de la rancune au lieu de prières.", "Остатки благовоний, в которых сгорала обида вместо молитв.", "Sisa dupa yang membakar dendam, bukan doa.", "祈りではなく恨みを燃やした線香の残りかす。", "기도 대신 원한을 태운 향의 찌꺼기.", "燃燒怨恨而非祈禱的線香殘渣。", "燃烧怨恨而非祈祷的线香残渣。"],
    "enemy.oni_small.name": ["Oni Pequeno", "Little Oni", "Oni Pequeño", "Kleiner Oni", "Petit oni", "Маленький они", "Oni Kecil", "小鬼", "작은 오니", "小鬼", "小鬼"],
    "enemy.oni_small.lore": ["Os aprendizes do inferno. Batem forte e riem mais alto ainda.", "Apprentices of hell. They hit hard and laugh even louder.", "Los aprendices del infierno. Golpean fuerte y ríen más fuerte aún.", "Lehrlinge der Hölle. Sie schlagen hart und lachen noch lauter.", "Les apprentis de l'enfer. Ils frappent fort et rient plus fort encore.", "Подмастерья ада. Бьют сильно, а смеются ещё громче.", "Murid neraka. Pukulannya keras, tawanya lebih keras.", "地獄の見習い。強く殴り、さらに大声で笑う。", "지옥의 견습생. 세게 때리고 더 크게 웃는다.", "地獄的學徒。出手很重，笑聲更響。", "地狱的学徒。出手很重，笑声更响。"],
    "enemy.bakeneko.name": ["Bakeneko", "Bakeneko", "Bakeneko", "Bakeneko", "Bakeneko", "Бакэнэко", "Bakeneko", "化け猫", "바케네코", "化貓", "化猫"],
    "enemy.bakeneko.lore": ["Um gato que viveu demais. Salta do telhado antes que você o veja.", "A cat that lived too long. It leaps from the roof before you see it.", "Un gato que vivió demasiado. Salta del tejado antes de que lo veas.", "Eine Katze, die zu lange lebte. Sie springt vom Dach, ehe du sie siehst.", "Un chat qui a trop vécu. Il bondit du toit avant que tu le voies.", "Кот, проживший слишком долго. Прыгает с крыши раньше, чем ты его заметишь.", "Kucing yang hidup terlalu lama. Ia melompat dari atap sebelum kau melihatnya.", "長く生きすぎた猫。気づく前に屋根から飛びかかる。", "너무 오래 산 고양이. 보기도 전에 지붕에서 덮친다.", "活得太久的貓。你還沒看見，牠就從屋頂撲下。", "活得太久的猫。你还没看见，它就从屋顶扑下。"],
    "enemy.bamboo_spirit.name": ["Espírito do Bambu", "Bamboo Spirit", "Espíritu del Bambú", "Bambusgeist", "Esprit du bambou", "Дух бамбука", "Roh Bambu", "竹の精", "대나무 정령", "竹之精", "竹之精"],
    "enemy.bamboo_spirit.lore": ["Repete a última frase que ouviu. Esta noite, repete gritos.", "It repeats the last words it heard. Tonight, it repeats screams.", "Repite la última frase que oyó. Esta noche repite gritos.", "Er wiederholt die letzten Worte, die er hörte. Heute Nacht wiederholt er Schreie.", "Il répète les derniers mots entendus. Cette nuit, il répète des cris.", "Повторяет последние услышанные слова. Этой ночью — крики.", "Ia mengulang kata terakhir yang didengarnya. Malam ini, ia mengulang jeritan.", "最後に聞いた言葉を繰り返す。今夜は悲鳴を繰り返している。", "마지막으로 들은 말을 되풀이한다. 오늘 밤은 비명을 되풀이한다.", "重複最後聽見的話。今夜，牠重複著尖叫。", "重复最后听见的话。今夜，它重复着尖叫。"],
    "enemy.bamboo_elder.name": ["Bambu Ancião", "Elder Bamboo", "Bambú Anciano", "Alter Bambus", "Bambou ancien", "Старый бамбук", "Bambu Tetua", "古竹", "늙은 대나무", "老竹", "老竹"],
    "enemy.bamboo_elder.lore": ["Lento como o crescimento de um século. Duro como ele também.", "Slow as a century of growth. Just as tough.", "Lento como el crecimiento de un siglo. Igual de duro.", "Langsam wie ein Jahrhundert Wachstum. Und genauso zäh.", "Lent comme un siècle de croissance. Aussi coriace.", "Медлителен, как вековой рост. И так же крепок.", "Lambat seperti pertumbuhan seabad. Sama kerasnya.", "百年の成長のように遅く、同じだけ硬い。", "백 년의 성장처럼 느리고, 그만큼 단단하다.", "像百年生長般緩慢，也一樣堅硬。", "像百年生长般缓慢，也一样坚硬。"],
    "enemy.kitsune_minor.name": ["Raposa de Fogo", "Fox-Fire Kitsune", "Zorro de Fuego", "Fuchsfeuer-Kitsune", "Renard de feu", "Огненная лиса", "Rubah Api", "狐火の狐", "여우불 여우", "狐火狐", "狐火狐"],
    "enemy.kitsune_minor.lore": ["Raposas jovens que aprendem a enganar acendendo luzes falsas no bosque.", "Young foxes learning to deceive by lighting false lights in the woods.", "Zorros jóvenes que aprenden a engañar encendiendo luces falsas en el bosque.", "Junge Füchse, die mit falschen Lichtern im Wald täuschen lernen.", "De jeunes renards qui apprennent à tromper en allumant de faux feux dans les bois.", "Молодые лисы учатся обманывать, зажигая в лесу ложные огни.", "Rubah muda yang belajar menipu dengan menyalakan cahaya palsu di hutan.", "森に偽の灯をともして欺くことを学ぶ若い狐。", "숲에 가짜 불빛을 밝히며 속이는 법을 배우는 어린 여우.", "在林中點起假火學習欺騙的年輕狐狸。", "在林中点起假火学习欺骗的年轻狐狸。"],
    "enemy.tsuchigumo_yellow.name": ["Tsuchigumo Dourada", "Golden Tsuchigumo", "Tsuchigumo Dorada", "Goldene Tsuchigumo", "Tsuchigumo dorée", "Золотая цутигумо", "Tsuchigumo Emas", "金の土蜘蛛", "황금 츠치구모", "金土蜘蛛", "金土蜘蛛"],
    "enemy.tsuchigumo_yellow.lore": ["Tece teias entre os bambus. Quem fica preso vira mais uma voz do bosque.", "It weaves webs between the bamboo. Whoever gets caught becomes another voice of the grove.", "Teje telarañas entre los bambúes. Quien queda atrapado se vuelve otra voz del bosque.", "Sie spinnt Netze zwischen Bambus. Wer sich verfängt, wird eine weitere Stimme des Hains.", "Elle tisse entre les bambous. Qui s'y prend devient une voix de plus du bois.", "Плетёт сети среди бамбука. Попавший в них становится ещё одним голосом рощи.", "Ia menenun jaring di antara bambu. Yang terjerat menjadi suara hutan berikutnya.", "竹の間に巣を張る。捕まった者は竹林の声の一つになる。", "대나무 사이에 거미줄을 친다. 걸린 자는 숲의 목소리가 된다.", "在竹間結網。被困者會成為竹林的另一個聲音。", "在竹间结网。被困者会成为竹林的另一个声音。"],
    "enemy.butterfly_swarm.name": ["Borboletas da Alma", "Soul Butterflies", "Mariposas del Alma", "Seelenfalter", "Papillons d'âme", "Бабочки душ", "Kupu-kupu Jiwa", "魂の蝶", "영혼 나비", "魂蝶", "魂蝶"],
    "enemy.butterfly_swarm.lore": ["Dizem que cada uma é uma alma a caminho do outro lado. Estas se perderam.", "They say each one is a soul on its way to the other side. These ones got lost.", "Dicen que cada una es un alma camino del otro lado. Estas se perdieron.", "Jeder Falter sei eine Seele auf dem Weg ins Jenseits. Diese haben sich verirrt.", "On dit que chacun est une âme en route vers l'autre rive. Ceux-ci se sont perdus.", "Говорят, каждая — душа на пути в иной мир. Эти заблудились.", "Konon tiap kupu-kupu adalah jiwa menuju seberang. Yang ini tersesat.", "一匹一匹があの世へ向かう魂だという。これらは道に迷った。", "하나하나가 저승으로 가는 영혼이라 한다. 이들은 길을 잃었다.", "傳說每一隻都是前往彼岸的靈魂。這些迷路了。", "传说每一只都是前往彼岸的灵魂。这些迷路了。"],
    "enemy.mushroom.name": ["Cogumelo Errante", "Wandering Mushroom", "Seta Errante", "Wanderpilz", "Champignon errant", "Бродячий гриб", "Jamur Pengembara", "さまよう茸", "떠도는 버섯", "流浪菇", "流浪菇"],
    "enemy.mushroom.lore": ["Brota onde alguém caiu na noite da procissão. Ao estourar, espalha mais de si.", "It sprouts where someone fell on procession night. When it bursts, it spreads more of itself.", "Brota donde alguien cayó la noche de la procesión. Al reventar, esparce más de sí.", "Er sprießt, wo in der Prozessionsnacht jemand fiel. Platzt er, verbreitet er sich.", "Il pousse là où quelqu'un est tombé la nuit de la procession. En éclatant, il se répand.", "Вырастает там, где кто-то пал в ночь шествия. Лопаясь, размножается.", "Tumbuh di tempat seseorang tumbang pada malam arak-arakan. Saat pecah, ia menyebar.", "行列の夜に誰かが倒れた場所に生える。弾けるとさらに増える。", "행렬의 밤에 누군가 쓰러진 자리에서 돋는다. 터지면 더 퍼진다.", "在百鬼夜有人倒下之處萌生。爆裂時會擴散更多。", "在百鬼夜有人倒下之处萌生。爆裂时会扩散更多。"],
    "enemy.ghost_monk.name": ["Monge Fantasma", "Ghost Monk", "Monje Fantasma", "Geistermönch", "Moine fantôme", "Призрачный монах", "Biksu Hantu", "幽霊僧", "유령 승려", "幽靈僧", "幽灵僧"],
    "enemy.ghost_monk.lore": ["Ainda recita os sutras da Ordem, mas cada palavra agora queima.", "It still recites the Order's sutras, but every word now burns.", "Aún recita los sutras de la Orden, pero cada palabra ahora quema.", "Er rezitiert noch die Sutren des Ordens, doch jedes Wort brennt nun.", "Il récite encore les sutras de l'Ordre, mais chaque mot brûle désormais.", "Он всё ещё читает сутры Ордена, но теперь каждое слово жжёт.", "Ia masih melantunkan sutra Ordo, tapi kini setiap kata membakar.", "今も教団の経を唱えるが、その一言一言が焼けつく。", "아직 결사의 경을 외지만, 이제 한 마디 한 마디가 타오른다.", "仍誦著教團的經文，但如今每個字都會灼人。", "仍诵着教团的经文，但如今每个字都会灼人。"],
    "enemy.lantern_obake.name": ["Chōchin-obake", "Chōchin-obake", "Chōchin-obake", "Chōchin-obake", "Chōchin-obake", "Тётин-обакэ", "Chōchin-obake", "提灯お化け", "초친오바케", "提燈妖怪", "提灯妖怪"],
    "enemy.lantern_obake.lore": ["Uma lanterna de papel que ganhou língua e dentes. Tem inveja da sua chama.", "A paper lantern that grew a tongue and teeth. It envies your flame.", "Una linterna de papel a la que le crecieron lengua y dientes. Envidia tu llama.", "Eine Papierlaterne mit Zunge und Zähnen. Sie neidet dir deine Flamme.", "Une lanterne de papier dotée d'une langue et de dents. Elle envie ta flamme.", "Бумажный фонарь, у которого выросли язык и зубы. Завидует твоему пламени.", "Lentera kertas yang tumbuh lidah dan gigi. Ia iri pada apimu.", "舌と歯の生えた紙の提灯。お前の炎を妬んでいる。", "혀와 이빨이 돋은 종이 등롱. 네 불꽃을 시기한다.", "長出舌頭與牙齒的紙燈籠。牠嫉妒你的火焰。", "长出舌头与牙齿的纸灯笼。它嫉妒你的火焰。"],
    "enemy.lantern_wisp.name": ["Fogo-Fátuo Verde", "Green Wisp", "Fuego Fatuo Verde", "Grünes Irrlicht", "Feu follet vert", "Зелёный блуждающий огонёк", "Api Siluman Hijau", "緑の鬼火", "초록 도깨비불", "綠色鬼火", "绿色鬼火"],
    "enemy.lantern_wisp.lore": ["Uma luz que imita a lanterna da Ordem para atrair guardiões para longe.", "A light that mimics the Order's lantern to lure guardians away.", "Una luz que imita la linterna de la Orden para alejar a los guardianes.", "Ein Licht, das die Ordenslaterne nachahmt, um Wächter fortzulocken.", "Une lueur qui imite la lanterne de l'Ordre pour égarer les gardiens.", "Свет, подражающий фонарю Ордена, чтобы увести стражей прочь.", "Cahaya yang meniru lentera Ordo untuk memancing penjaga menjauh.", "教団の灯籠を真似て守り人を誘い出す光。", "결사의 등불을 흉내 내 수호자를 꾀어내는 빛.", "模仿教團燈籠引誘守護者離開的光。", "模仿教团灯笼引诱守护者离开的光。"],
    "enemy.skull.name": ["Caveira Errante", "Wandering Skull", "Calavera Errante", "Wandernder Schädel", "Crâne errant", "Блуждающий череп", "Tengkorak Pengembara", "さまよう髑髏", "떠도는 해골", "遊蕩骷髏", "游荡骷髅"],
    "enemy.skull.lore": ["Não lembra de quem foi. Só lembra que estava com fome.", "It doesn't remember who it was. Only that it was hungry.", "No recuerda quién fue. Solo que tenía hambre.", "Er weiß nicht mehr, wer er war. Nur, dass er Hunger hatte.", "Il ne se rappelle pas qui il était. Seulement qu'il avait faim.", "Не помнит, кем был. Помнит лишь, что был голоден.", "Ia tak ingat siapa dirinya. Hanya ingat sedang lapar.", "誰だったかは覚えていない。腹が減っていたことだけ覚えている。", "누구였는지 기억하지 못한다. 배고팠다는 것만 기억한다.", "不記得自己是誰，只記得很餓。", "不记得自己是谁，只记得很饿。"],
    "enemy.hyakume.name": ["Hyakume", "Hyakume", "Hyakume", "Hyakume", "Hyakume", "Хякумэ", "Hyakume", "百目", "햐쿠메", "百目", "百目"],
    "enemy.hyakume.lore": ["O yōkai dos cem olhos vigiava o tesouro do templo. Agora vigia você.", "The hundred-eyed yōkai once watched the temple treasure. Now it watches you.", "El yōkai de cien ojos vigilaba el tesoro del templo. Ahora te vigila a ti.", "Der hundertäugige Yōkai bewachte den Tempelschatz. Jetzt bewacht er dich.", "Le yōkai aux cent yeux gardait le trésor du temple. Désormais, il te surveille.", "Стоглазый ёкай сторожил сокровища храма. Теперь он следит за тобой.", "Yōkai bermata seratus dulu menjaga harta kuil. Kini ia mengawasimu.", "寺の宝を見張っていた百の目の妖怪。今はお前を見張っている。", "사원의 보물을 지키던 백 개의 눈 요괴. 이제는 너를 지켜본다.", "百眼妖怪曾守著寺院寶物，如今盯著你。", "百眼妖怪曾守着寺院宝物，如今盯着你。"],
    "enemy.tengu_crow.name": ["Karasu-tengu", "Karasu-tengu", "Karasu-tengu", "Karasu-Tengu", "Karasu-tengu", "Карасу-тэнгу", "Karasu-tengu", "烏天狗", "까마귀 텐구", "烏天狗", "乌天狗"],
    "enemy.tengu_crow.lore": ["Guerreiros-corvo das montanhas. Mergulham sobre quem baixa a guarda.", "Crow warriors of the mountains. They dive on anyone who lowers their guard.", "Guerreros cuervo de las montañas. Se lanzan sobre quien baja la guardia.", "Krähenkrieger der Berge. Sie stoßen auf jeden herab, der die Deckung senkt.", "Guerriers-corbeaux des montagnes. Ils fondent sur qui baisse sa garde.", "Горные воины-вороны. Пикируют на всех, кто теряет бдительность.", "Prajurit gagak pegunungan. Menukik pada siapa pun yang lengah.", "山の烏の戦士。隙を見せた者に急降下する。", "산의 까마귀 전사. 방심한 자에게 내리꽂힌다.", "山中的烏鴉戰士，俯衝撲向鬆懈之人。", "山中的乌鸦战士，俯冲扑向松懈之人。"],
    "enemy.owl.name": ["Coruja Agourenta", "Omen Owl", "Búho Agorero", "Unheilseule", "Chouette de mauvais augure", "Сова-вестница", "Burung Hantu Pertanda", "凶兆の梟", "흉조 올빼미", "凶兆貓頭鷹", "凶兆猫头鹰"],
    "enemy.owl.lore": ["Pia três vezes antes de cada morte. Esta noite, não para de piar.", "It hoots three times before every death. Tonight it won't stop hooting.", "Ulula tres veces antes de cada muerte. Esta noche no deja de ulular.", "Sie ruft dreimal vor jedem Tod. Heute Nacht hört sie nicht auf.", "Elle hulule trois fois avant chaque mort. Cette nuit, elle ne s'arrête pas.", "Ухает трижды перед каждой смертью. Этой ночью не умолкает.", "Ia berbunyi tiga kali sebelum tiap kematian. Malam ini ia tak berhenti.", "死の前に三度鳴く。今夜は鳴きやまない。", "죽음 앞에서 세 번 운다. 오늘 밤은 울음을 멈추지 않는다.", "每次死亡前叫三聲。今夜，牠叫個不停。", "每次死亡前叫三声。今夜，它叫个不停。"],
    "enemy.cyclops_stone.name": ["Hitotsume de Pedra", "Stone Hitotsume", "Hitotsume de Piedra", "Stein-Hitotsume", "Hitotsume de pierre", "Каменный хитоцумэ", "Hitotsume Batu", "石の一つ目", "돌 외눈박이", "石獨眼", "石独眼"],
    "enemy.cyclops_stone.lore": ["Estátuas que guardavam a estrada. Kuroe passou e elas abriram o único olho.", "Statues that guarded the road. Kuroe passed by, and they opened their single eye.", "Estatuas que guardaban el camino. Kuroe pasó y abrieron su único ojo.", "Statuen, die die Straße bewachten. Kuroe zog vorbei, und sie öffneten ihr einziges Auge.", "Des statues gardiennes de la route. Kuroe est passé, et elles ont ouvert leur œil unique.", "Статуи, охранявшие дорогу. Прошёл Куроэ — и они открыли свой единственный глаз.", "Patung penjaga jalan. Kuroe lewat, dan mereka membuka satu-satunya mata.", "道を守っていた石像。黒衛が通り過ぎ、その一つ目を開いた。", "길을 지키던 석상. 쿠로에가 지나가자 외눈을 떴다.", "守路的石像。黑衛經過後，它們睜開了獨眼。", "守路的石像。黑卫经过后，它们睁开了独眼。"],
    "enemy.cyclops_ash.name": ["Hitotsume de Cinza", "Ash Hitotsume", "Hitotsume de Ceniza", "Asche-Hitotsume", "Hitotsume de cendre", "Пепельный хитоцумэ", "Hitotsume Abu", "灰の一つ目", "잿빛 외눈박이", "灰獨眼", "灰独眼"],
    "enemy.cyclops_ash.lore": ["Mais pesado que a pedra e mais quente que a forja. Cada passo deixa uma marca.", "Heavier than stone and hotter than the forge. Every step leaves a mark.", "Más pesado que la piedra y más caliente que la forja. Cada paso deja huella.", "Schwerer als Stein, heißer als die Schmiede. Jeder Schritt hinterlässt Spuren.", "Plus lourd que la pierre, plus chaud que la forge. Chaque pas laisse une trace.", "Тяжелее камня и горячее кузни. Каждый шаг оставляет след.", "Lebih berat dari batu, lebih panas dari tungku. Tiap langkah meninggalkan bekas.", "石より重く、鍛冶場より熱い。一歩ごとに跡が残る。", "돌보다 무겁고 대장간보다 뜨겁다. 걸음마다 자국이 남는다.", "比石頭重，比鍛爐燙。每一步都留下痕跡。", "比石头重，比锻炉烫。每一步都留下痕迹。"],
    "enemy.ash_larva.name": ["Larva de Cinza", "Ash Larva", "Larva de Ceniza", "Aschelarve", "Larve de cendre", "Пепельная личинка", "Larva Abu", "灰の幼虫", "잿빛 애벌레", "灰燼幼蟲", "灰烬幼虫"],
    "enemy.ash_larva.lore": ["Nasce do que sobrou do fogo. Quando morre, se divide e nasce de novo.", "Born from what the fire left behind. When it dies, it splits and is born again.", "Nace de lo que dejó el fuego. Al morir, se divide y renace.", "Geboren aus dem, was das Feuer übrig ließ. Stirbt sie, teilt sie sich und wird neu geboren.", "Née de ce que le feu a laissé. En mourant, elle se divise et renaît.", "Рождается из того, что оставил огонь. Умирая, делится и рождается вновь.", "Lahir dari sisa api. Saat mati, ia membelah dan lahir lagi.", "火の残りから生まれる。死ぬと分かれ、また生まれる。", "불이 남긴 것에서 태어난다. 죽으면 갈라져 다시 태어난다.", "誕生於火焰殘餘。死時會分裂並重生。", "诞生于火焰残余。死时会分裂并重生。"],
    "enemy.sand_lizard.name": ["Lagarto das Dunas", "Dune Lizard", "Lagarto de las Dunas", "Dünenechse", "Lézard des dunes", "Дюнная ящерица", "Kadal Bukit Pasir", "砂丘トカゲ", "사구 도마뱀", "沙丘蜥蜴", "沙丘蜥蜴"],
    "enemy.sand_lizard.lore": ["Dorme sob a cinza quente e dispara quando sente passos.", "It sleeps under the warm ash and bolts when it feels footsteps.", "Duerme bajo la ceniza caliente y se lanza al sentir pasos.", "Sie schläft unter warmer Asche und schießt hervor, wenn sie Schritte spürt.", "Il dort sous la cendre chaude et bondit au moindre pas.", "Спит под тёплым пеплом и бросается, почуяв шаги.", "Tidur di bawah abu hangat dan melesat saat merasakan langkah.", "熱い灰の下で眠り、足音を感じると飛び出す。", "뜨거운 재 아래 자다가 발소리를 느끼면 튀어나온다.", "睡在溫熱灰燼下，一感到腳步就疾衝而出。", "睡在温热灰烬下，一感到脚步就疾冲而出。"],
    "enemy.dune_snake.name": ["Serpente de Cinza", "Ash Serpent", "Serpiente de Ceniza", "Ascheschlange", "Serpent de cendre", "Пепельный змей", "Ular Abu", "灰の蛇", "잿빛 뱀", "灰燼之蛇", "灰烬之蛇"],
    "enemy.dune_snake.lore": ["Desliza pelas dunas como fumaça rasteira. Seu veneno tem gosto de carvão.", "It slides over the dunes like low smoke. Its venom tastes of charcoal.", "Se desliza por las dunas como humo rastrero. Su veneno sabe a carbón.", "Sie gleitet wie tiefer Rauch über die Dünen. Ihr Gift schmeckt nach Kohle.", "Il glisse sur les dunes comme une fumée rasante. Son venin a un goût de charbon.", "Скользит по дюнам, как стелющийся дым. Её яд на вкус как уголь.", "Meluncur di bukit seperti asap rendah. Bisanya terasa seperti arang.", "低い煙のように砂丘を這う。毒は炭の味がする。", "낮게 깔린 연기처럼 사구를 미끄러진다. 독에서 숯 맛이 난다.", "像低伏的煙般滑過沙丘。毒液帶著炭味。", "像低伏的烟般滑过沙丘。毒液带着炭味。"],
    "enemy.mole_digger.name": ["Toupeira Escavadora", "Digging Mole", "Topo Excavador", "Grabender Maulwurf", "Taupe fouisseuse", "Крот-копатель", "Tikus Tanah Penggali", "穴掘りモグラ", "땅파기 두더지", "掘地鼴鼠", "掘地鼹鼠"],
    "enemy.mole_digger.lore": ["Cava túneis sob a cinza procurando o que Kuroe enterrou.", "It digs tunnels under the ash, searching for what Kuroe buried.", "Cava túneles bajo la ceniza buscando lo que Kuroe enterró.", "Sie gräbt Tunnel unter der Asche und sucht, was Kuroe vergrub.", "Elle creuse des tunnels sous la cendre, cherchant ce que Kuroe a enterré.", "Роет ходы под пеплом в поисках того, что закопал Куроэ.", "Menggali terowongan di bawah abu, mencari yang dikubur Kuroe.", "黒衛が埋めたものを探して、灰の下に穴を掘る。", "쿠로에가 묻은 것을 찾아 재 밑에 굴을 판다.", "在灰燼下挖掘隧道，尋找黑衛埋下的東西。", "在灰烬下挖掘隧道，寻找黑卫埋下的东西。"],
    "enemy.flame_spirit.name": ["Espírito da Chama", "Flame Spirit", "Espíritu de la Llama", "Flammengeist", "Esprit de flamme", "Дух пламени", "Roh Api", "炎の精", "불꽃 정령", "火焰之精", "火焰之精"],
    "enemy.flame_spirit.lore": ["Uma faísca da lanterna de Kuroe que se recusou a apagar.", "A spark from Kuroe's lantern that refused to go out.", "Una chispa de la linterna de Kuroe que se negó a apagarse.", "Ein Funke aus Kuroes Laterne, der nicht erlöschen wollte.", "Une étincelle de la lanterne de Kuroe qui a refusé de s'éteindre.", "Искра из фонаря Куроэ, отказавшаяся гаснуть.", "Percikan dari lentera Kuroe yang menolak padam.", "消えることを拒んだ黒衛の灯籠の火の粉。", "꺼지기를 거부한 쿠로에 등불의 불똥.", "黑衛燈籠中拒絕熄滅的火星。", "黑卫灯笼中拒绝熄灭的火星。"],
    "enemy.oni_green.name": ["Oni Verde", "Green Oni", "Oni Verde", "Grüner Oni", "Oni vert", "Зелёный они", "Oni Hijau", "青鬼", "푸른 오니", "青鬼", "青鬼"],
    "enemy.oni_green.lore": ["O carcereiro do Yomi. Não corre, porque ninguém nunca escapou dele.", "Yomi's jailer. It doesn't run, because no one has ever escaped it.", "El carcelero del Yomi. No corre, porque nadie se le ha escapado nunca.", "Der Kerkermeister von Yomi. Er rennt nicht, denn niemand entkam ihm je.", "Le geôlier du Yomi. Il ne court pas : personne ne lui a jamais échappé.", "Тюремщик Ёми. Он не бегает, ведь от него ещё никто не уходил.", "Sipir Yomi. Ia tak berlari, karena tak ada yang pernah lolos darinya.", "黄泉の牢番。走らない。誰も逃げられたことがないからだ。", "황천의 옥졸. 달리지 않는다. 아무도 그에게서 도망친 적이 없으니까.", "黃泉的獄卒。牠不奔跑，因為從沒人逃得掉。", "黄泉的狱卒。它不奔跑，因为从没人逃得掉。"],
    "enemy.yurei.name": ["Yūrei", "Yūrei", "Yūrei", "Yūrei", "Yūrei", "Юрэй", "Yūrei", "幽霊", "유령", "幽靈", "幽灵"],
    "enemy.yurei.lore": ["Almas com um assunto inacabado. Somem na luz e reaparecem no escuro.", "Souls with unfinished business. They vanish in the light and return in the dark.", "Almas con asuntos pendientes. Desaparecen en la luz y vuelven en la oscuridad.", "Seelen mit unerledigten Dingen. Sie vergehen im Licht und kehren im Dunkeln zurück.", "Des âmes aux affaires inachevées. Elles disparaissent dans la lumière et reviennent dans le noir.", "Души с незавершёнными делами. Исчезают на свету и возвращаются во тьме.", "Jiwa dengan urusan belum selesai. Lenyap di cahaya, kembali di gelap.", "未練を残した魂。光の中で消え、闇に戻る。", "한을 남긴 영혼. 빛 속에서 사라지고 어둠 속에서 돌아온다.", "心有未了的亡魂。在光中消失，在暗中重現。", "心有未了的亡魂。在光中消失，在暗中重现。"],
    "enemy.skeleton_demon.name": ["Gashadokuro Menor", "Lesser Gashadokuro", "Gashadokuro Menor", "Kleiner Gashadokuro", "Petit gashadokuro", "Малый гасядокуро", "Gashadokuro Kecil", "小がしゃどくろ", "작은 가샤도쿠로", "小餓者髑髏", "小饿者髑髅"],
    "enemy.skeleton_demon.lore": ["Feito dos ossos de quem morreu de fome. Atira lascas de si mesmo.", "Made from the bones of those who starved. It hurls splinters of itself.", "Hecho con los huesos de quienes murieron de hambre. Lanza astillas de sí mismo.", "Aus den Knochen Verhungerter. Es schleudert Splitter seiner selbst.", "Fait des os de ceux morts de faim. Il projette des éclats de lui-même.", "Сложен из костей умерших от голода. Мечет осколки себя самого.", "Terbuat dari tulang mereka yang mati kelaparan. Melempar serpihan dirinya.", "飢え死にした者の骨でできている。自らの骨片を投げつける。", "굶어 죽은 자들의 뼈로 만들어졌다. 자기 뼛조각을 던진다.", "由餓死者骨骸組成，會擲出自己的碎骨。", "由饿死者骨骸组成，会掷出自己的碎骨。"],
    "enemy.yomi_eye.name": ["Olho do Yomi", "Eye of Yomi", "Ojo del Yomi", "Auge von Yomi", "Œil du Yomi", "Око Ёми", "Mata Yomi", "黄泉の眼", "황천의 눈", "黃泉之眼", "黄泉之眼"],
    "enemy.yomi_eye.lore": ["O Yomi olha para o mundo dos vivos através destes olhos. Gosta do que vê.", "Yomi looks upon the living world through these eyes. It likes what it sees.", "El Yomi mira el mundo de los vivos a través de estos ojos. Le gusta lo que ve.", "Yomi blickt durch diese Augen auf die Welt der Lebenden. Ihm gefällt, was es sieht.", "Le Yomi regarde le monde des vivants par ces yeux. Il aime ce qu'il voit.", "Ёми смотрит на мир живых этими глазами. Ему нравится увиденное.", "Yomi memandang dunia orang hidup lewat mata ini. Ia suka yang dilihatnya.", "黄泉はこの眼を通して生者の世を見る。見たものが気に入っている。", "황천은 이 눈으로 산 자의 세상을 본다. 보이는 것이 마음에 든다.", "黃泉透過這些眼睛注視生者之世，並且很喜歡所見。", "黄泉透过这些眼睛注视生者之世，并且很喜欢所见。"],
    "enemy.yomi_beast.name": ["Fera do Yomi", "Yomi Beast", "Bestia del Yomi", "Yomi-Bestie", "Bête du Yomi", "Зверь Ёми", "Binatang Yomi", "黄泉の獣", "황천의 짐승", "黃泉之獸", "黄泉之兽"],
    "enemy.yomi_beast.lore": ["Os cães de caça da procissão. Farejam a luz a quilômetros.", "The procession's hunting hounds. They smell light from miles away.", "Los sabuesos de la procesión. Huelen la luz a kilómetros.", "Die Jagdhunde der Prozession. Sie wittern Licht meilenweit.", "Les chiens de chasse de la procession. Ils flairent la lumière à des lieues.", "Гончие шествия. Чуют свет за версту.", "Anjing pemburu arak-arakan. Mereka mencium cahaya dari jauh.", "行列の猟犬。何里も先の光を嗅ぎつける。", "행렬의 사냥개. 먼 곳의 빛도 냄새로 찾는다.", "百鬼的獵犬，遠在數里外就能嗅到光。", "百鬼的猎犬，远在数里外就能嗅到光。"],
    "enemy.skull_blue.name": ["Caveira Azul", "Blue Skull", "Calavera Azul", "Blauer Schädel", "Crâne bleu", "Синий череп", "Tengkorak Biru", "青い髑髏", "푸른 해골", "藍骷髏", "蓝骷髅"],
    "enemy.skull_blue.lore": ["Queima com o fogo frio do Yomi. Seu toque congela a alma.", "It burns with Yomi's cold fire. Its touch freezes the soul.", "Arde con el fuego frío del Yomi. Su toque congela el alma.", "Er brennt mit Yomis kaltem Feuer. Seine Berührung lässt die Seele gefrieren.", "Il brûle du feu froid du Yomi. Son contact glace l'âme.", "Горит холодным огнём Ёми. Его касание леденит душу.", "Terbakar api dingin Yomi. Sentuhannya membekukan jiwa.", "黄泉の冷たい火で燃える。触れれば魂が凍る。", "황천의 차가운 불로 탄다. 닿으면 영혼이 얼어붙는다.", "燃著黃泉的冷火，觸碰即凍結靈魂。", "燃着黄泉的冷火，触碰即冻结灵魂。"],
    "enemy.yomi_drake.name": ["Dragão do Yomi", "Yomi Drake", "Draco del Yomi", "Yomi-Drache", "Dragonnet du Yomi", "Дракон Ёми", "Naga Yomi", "黄泉の竜", "황천의 용", "黃泉之龍", "黄泉之龙"],
    "enemy.yomi_drake.lore": ["Dorme nas raízes do mundo e só acorda quando os tambores tocam.", "It sleeps at the roots of the world and only wakes when the drums play.", "Duerme en las raíces del mundo y solo despierta cuando suenan los tambores.", "Er schläft an den Wurzeln der Welt und erwacht nur, wenn die Trommeln schlagen.", "Il dort aux racines du monde et ne s'éveille qu'au son des tambours.", "Спит у корней мира и просыпается лишь под барабаны.", "Tidur di akar dunia dan hanya bangun saat genderang ditabuh.", "世界の根で眠り、太鼓が鳴る時だけ目覚める。", "세상의 뿌리에서 잠들었다가 북이 울릴 때만 깨어난다.", "沉睡於世界之根，唯有鼓響才會甦醒。", "沉睡于世界之根，唯有鼓响才会苏醒。"],
    "enemy.yomi_beast_dark.name": ["Fera da Encosta", "Slope Beast", "Bestia de la Ladera", "Hangbestie", "Bête de la pente", "Зверь склона", "Binatang Lereng", "坂の獣", "언덕의 짐승", "坡道之獸", "坡道之兽"],
    "enemy.yomi_beast_dark.lore": ["Guarda a fronteira dos mortos. Nunca deixou ninguém voltar.", "It guards the border of the dead. It has never let anyone return.", "Guarda la frontera de los muertos. Nunca dejó volver a nadie.", "Sie bewacht die Grenze der Toten. Nie ließ sie jemanden zurück.", "Elle garde la frontière des morts. Elle n'a jamais laissé personne revenir.", "Стережёт границу мёртвых. Никого ещё не отпустил назад.", "Menjaga batas orang mati. Tak pernah membiarkan siapa pun kembali.", "死者の境を守る。誰一人戻らせたことはない。", "망자의 경계를 지킨다. 누구도 돌아가게 둔 적이 없다.", "守護亡者邊界，從未讓任何人回去。", "守护亡者边界，从未让任何人回去。"],
    # Chefes
    "boss.tanuki.name": ["Tanuki Gigante", "Giant Tanuki", "Tanuki Gigante", "Riesen-Tanuki", "Tanuki géant", "Гигантский тануки", "Tanuki Raksasa", "大狸", "거대 너구리", "巨狸", "巨狸"],
    "boss.tanuki.line": ["Essa vila é minha agora. Quer apostar?", "This village is mine now. Care to bet?", "Esta aldea es mía ahora. ¿Apostamos?", "Dieses Dorf gehört jetzt mir. Wetten?", "Ce village est à moi. On parie ?", "Теперь эта деревня моя. Поспорим?", "Desa ini milikku sekarang. Mau bertaruh?", "この村はもう俺のもんだ。賭けるか？", "이 마을은 이제 내 거다. 내기할래?", "這村子現在歸我了。要不要賭一把？", "这村子现在归我了。要不要赌一把？"],
    "boss.tanuki.lore": ["Ganhou a vila numa aposta com um oni. Ainda não descobriu que o dado era viciado — por ele mesmo.", "It won the village in a bet with an oni. It hasn't realized the die was loaded — by itself.", "Ganó la aldea en una apuesta con un oni. Aún no sabe que el dado estaba trucado, por él mismo.", "Er gewann das Dorf in einer Wette mit einem Oni. Er hat noch nicht gemerkt, dass er den Würfel selbst gezinkt hatte.", "Il a gagné le village en pariant avec un oni. Il ignore encore que le dé était pipé — par lui-même.", "Выиграл деревню в споре с они. До сих пор не понял, что кость была с подвохом — его собственным.", "Ia memenangkan desa dari taruhan dengan oni. Ia belum sadar dadunya curang — olehnya sendiri.", "鬼との賭けで村を手に入れた。賽がいかさまだったと、まだ気づいていない——仕込んだのは自分なのに。", "오니와의 내기로 마을을 얻었다. 주사위가 조작된 걸 아직 모른다. 조작한 건 자신인데도.", "與鬼打賭贏得村莊。牠還沒發現骰子動過手腳——是牠自己動的。", "与鬼打赌赢得村庄。它还没发现骰子动过手脚——是它自己动的。"],
    "boss.kappa_elder.name": ["Kappa Ancião", "Elder Kappa", "Kappa Anciano", "Alter Kappa", "Kappa ancien", "Старый каппа", "Kappa Tetua", "河童の長老", "갓파 장로", "河童長老", "河童长老"],
    "boss.kappa_elder.line": ["A água do arrozal lembra de você, menina.", "The paddy water remembers you, girl.", "El agua del arrozal te recuerda, niña.", "Das Wasser der Reisfelder erinnert sich an dich, Mädchen.", "L'eau de la rizière se souvient de toi, petite.", "Вода рисовых полей помнит тебя, девочка.", "Air sawah masih mengingatmu, Nak.", "田の水はお前を覚えているぞ、娘。", "논물이 너를 기억한다, 아가.", "稻田的水還記得妳，小姑娘。", "稻田的水还记得你，小姑娘。"],
    "boss.kappa_elder.lore": ["Viu Aki brincar no arrozal há cem anos. É o único que se lembra do rosto dela.", "It saw Aki play in the paddies a hundred years ago. It is the only one who remembers her face.", "Vio a Aki jugar en el arrozal hace cien años. Es el único que recuerda su rostro.", "Er sah Aki vor hundert Jahren im Reisfeld spielen. Nur er erinnert sich an ihr Gesicht.", "Il a vu Aki jouer dans la rizière il y a cent ans. Lui seul se souvient de son visage.", "Видел, как Аки играла на рисовом поле сто лет назад. Только он помнит её лицо.", "Ia melihat Aki bermain di sawah seratus tahun lalu. Hanya ia yang ingat wajahnya.", "百年前、田んぼで遊ぶ灯を見ていた。彼女の顔を覚えている唯一の者だ。", "백 년 전 논에서 노는 아키를 보았다. 그녀의 얼굴을 기억하는 유일한 존재다.", "百年前見過燈在稻田玩耍。唯有牠還記得她的臉。", "百年前见过灯在稻田玩耍。唯有它还记得她的脸。"],
    "boss.bamboo_ancestral.name": ["Bambu Ancestral", "Ancestral Bamboo", "Bambú Ancestral", "Ahnenbambus", "Bambou ancestral", "Прадревний бамбук", "Bambu Leluhur", "祖竹", "조상 대나무", "祖竹", "祖竹"],
    "boss.bamboo_ancestral.line": ["Cem anos de raízes. Você cabe nelas.", "A hundred years of roots. You'll fit right in.", "Cien años de raíces. Cabes en ellas.", "Hundert Jahre Wurzeln. Du passt hinein.", "Cent ans de racines. Tu y trouveras ta place.", "Сто лет корней. Ты в них поместишься.", "Seratus tahun akar. Kau muat di dalamnya.", "百年の根。お前もそこに収まる。", "백 년의 뿌리. 너도 그 안에 들어간다.", "百年根系，你也容得下。", "百年根系，你也容得下。"],
    "boss.bamboo_ancestral.lore": ["A planta mais velha do bosque. Todas as vozes que o bambu repete nasceram nela.", "The oldest plant in the grove. Every voice the bamboo repeats was born in it.", "La planta más antigua del bosque. Todas las voces que repite el bambú nacieron en ella.", "Die älteste Pflanze des Hains. Jede Stimme, die der Bambus wiederholt, entstand in ihr.", "La plus vieille plante du bois. Toutes les voix que répète le bambou y sont nées.", "Старейшее растение рощи. Все голоса, что повторяет бамбук, родились в нём.", "Tumbuhan tertua di hutan. Semua suara yang diulang bambu lahir darinya.", "竹林で最も古い竹。竹が繰り返す声はすべてここから生まれた。", "숲에서 가장 오래된 대나무. 대나무가 되풀이하는 모든 목소리가 여기서 태어났다.", "竹林中最古老的植物。竹子重複的每個聲音都誕生於它。", "竹林中最古老的植物。竹子重复的每个声音都诞生于它。"],
    "boss.kitsune_nine.name": ["Kitsune de Nove Caudas", "Nine-Tailed Kitsune", "Kitsune de Nueve Colas", "Neunschwänzige Kitsune", "Kitsune à neuf queues", "Девятихвостая кицунэ", "Kitsune Ekor Sembilan", "九尾の狐", "구미호", "九尾狐", "九尾狐"],
    "boss.kitsune_nine.line": ["Aki... Aki... Reconhece essa voz?", "Aki... Aki... Do you know this voice?", "Aki... Aki... ¿Reconoces esta voz?", "Aki... Aki... Kennst du diese Stimme?", "Aki... Aki... Tu reconnais cette voix ?", "Аки... Аки... Узнаёшь этот голос?", "Aki... Aki... Kau kenal suara ini?", "灯……灯……この声に覚えは？", "아키... 아키... 이 목소리 알아?", "燈……燈……認得這聲音嗎？", "灯……灯……认得这声音吗？"],
    "boss.kitsune_nine.lore": ["Imita qualquer voz que já ouviu. Ouviu um homem chamar a filha por cem anos e aprendeu a voz dele.", "It mimics any voice it has heard. It heard a man calling for his daughter for a hundred years and learned his voice.", "Imita cualquier voz que haya oído. Oyó a un hombre llamar a su hija durante cien años y aprendió su voz.", "Sie ahmt jede Stimme nach. Hundert Jahre hörte sie einen Mann nach seiner Tochter rufen und lernte seine Stimme.", "Elle imite toute voix entendue. Elle a entendu un homme appeler sa fille pendant cent ans et a appris sa voix.", "Подражает любому услышанному голосу. Сто лет слушала, как мужчина звал дочь, и выучила его голос.", "Ia meniru suara apa pun yang pernah didengar. Seratus tahun ia mendengar seorang pria memanggil putrinya, dan mempelajari suaranya.", "聞いた声を何でも真似る。百年もの間、娘を呼ぶ男の声を聞き、それを覚えた。", "들은 목소리는 무엇이든 흉내 낸다. 백 년간 딸을 부르는 남자의 목소리를 듣고 그것을 익혔다.", "能模仿聽過的任何聲音。牠聽了一個男人呼喚女兒整整百年，學會了他的聲音。", "能模仿听过的任何声音。它听了一个男人呼唤女儿整整百年，学会了他的声音。"],
    "boss.tengu_crow_king.name": ["Rei Tengu Corvo", "Crow Tengu King", "Rey Tengu Cuervo", "Krähentengu-König", "Roi tengu corbeau", "Король вороньих тэнгу", "Raja Tengu Gagak", "烏天狗の王", "까마귀 텐구 왕", "烏天狗王", "乌天狗王"],
    "boss.tengu_crow_king.line": ["Guardiões caem. Eu vi todos caírem.", "Guardians fall. I watched them all fall.", "Los guardianes caen. Los vi caer a todos.", "Wächter fallen. Ich sah sie alle fallen.", "Les gardiens tombent. Je les ai tous vus tomber.", "Стражи падают. Я видел, как пали все.", "Penjaga jatuh. Aku melihat semuanya jatuh.", "守り人は倒れる。全員が倒れるのを見てきた。", "수호자는 쓰러진다. 모두 쓰러지는 걸 봤다.", "守護者會倒下。我看著他們全都倒下。", "守护者会倒下。我看着他们全都倒下。"],
    "boss.tengu_crow_king.lore": ["Pousava no telhado do templo na noite da queda. Nunca contou a ninguém o que viu.", "It perched on the temple roof on the night of the fall. It never told anyone what it saw.", "Se posaba en el tejado del templo la noche de la caída. Nunca contó lo que vio.", "In der Nacht des Falls saß er auf dem Tempeldach. Er erzählte niemandem, was er sah.", "Il était perché sur le toit du temple la nuit de la chute. Il n'a jamais dit ce qu'il a vu.", "В ночь падения он сидел на крыше храма. Никому не рассказал, что видел.", "Ia hinggap di atap kuil pada malam keruntuhan. Tak pernah bercerita apa yang dilihatnya.", "陥落の夜、寺の屋根にとまっていた。見たものを誰にも語らなかった。", "함락의 밤, 사원 지붕에 앉아 있었다. 본 것을 누구에게도 말하지 않았다.", "陷落之夜，牠棲在寺院屋頂。從未告訴任何人牠看見了什麼。", "陷落之夜，它栖在寺院屋顶。从未告诉任何人它看见了什么。"],
    "boss.faceless_monk.name": ["Monge Sem Rosto", "Faceless Monk", "Monje Sin Rostro", "Gesichtsloser Mönch", "Moine sans visage", "Безликий монах", "Biksu Tanpa Wajah", "顔なしの僧", "얼굴 없는 승려", "無面僧", "无面僧"],
    "boss.faceless_monk.line": ["Eu fiquei. Onde você estava?", "I stayed. Where were you?", "Yo me quedé. ¿Dónde estabas tú?", "Ich blieb. Wo warst du?", "Moi, je suis resté. Où étais-tu ?", "Я остался. А где был ты?", "Aku tetap tinggal. Di mana kau?", "私は残った。お前はどこにいた？", "나는 남았다. 너는 어디 있었나?", "我留下了。你在哪裡？", "我留下了。你在哪里？"],
    "boss.faceless_monk.lore": ["Ele deu o rosto para segurar a porta do templo. A porta caiu mesmo assim.", "He gave his face to hold the temple door. The door fell anyway.", "Dio su rostro para sostener la puerta del templo. La puerta cayó de todos modos.", "Er gab sein Gesicht, um das Tempeltor zu halten. Das Tor fiel trotzdem.", "Il a donné son visage pour tenir la porte du temple. La porte est tombée quand même.", "Он отдал лицо, чтобы удержать врата храма. Врата всё равно пали.", "Ia menyerahkan wajahnya untuk menahan pintu kuil. Pintu itu tetap runtuh.", "寺の門を支えるため顔を差し出した。それでも門は倒れた。", "사원의 문을 지키려 얼굴을 내주었다. 그래도 문은 무너졌다.", "他獻出臉孔撐住寺門。門還是倒了。", "他献出脸孔撑住寺门。门还是倒了。"],
    "boss.stone_cyclops.name": ["Ciclope de Pedra", "Stone Cyclops", "Cíclope de Piedra", "Steinzyklop", "Cyclope de pierre", "Каменный циклоп", "Siklop Batu", "石の巨人", "돌 거인", "石巨人", "石巨人"],
    "boss.stone_cyclops.line": ["Ele passou por aqui. Só sobrou eu.", "He came through here. Only I remain.", "Él pasó por aquí. Solo quedé yo.", "Er kam hier durch. Nur ich blieb übrig.", "Il est passé par ici. Il ne reste que moi.", "Он прошёл здесь. Остался лишь я.", "Ia lewat sini. Hanya aku yang tersisa.", "あの方はここを通った。残ったのは俺だけだ。", "그분이 여길 지나갔다. 남은 건 나뿐이다.", "他從這裡經過。只剩下我。", "他从这里经过。只剩下我。"],
    "boss.stone_cyclops.lore": ["O guardião de pedra da estrada. Tudo ao redor virou cinza; ele era duro demais para queimar.", "The road's stone guardian. Everything around it turned to ash; it was too hard to burn.", "El guardián de piedra del camino. Todo a su alrededor se volvió ceniza; era demasiado duro para arder.", "Der steinerne Wächter der Straße. Alles ringsum wurde Asche; er war zu hart zum Brennen.", "Le gardien de pierre de la route. Tout autour est devenu cendre ; lui était trop dur pour brûler.", "Каменный страж дороги. Всё вокруг стало пеплом; он был слишком твёрд, чтобы сгореть.", "Penjaga batu jalan. Segala di sekitarnya jadi abu; ia terlalu keras untuk terbakar.", "道の石の守護者。周りは全て灰になったが、彼は燃えるには硬すぎた。", "길의 돌 수호자. 주위가 모두 재가 됐지만, 그는 타기엔 너무 단단했다.", "道路的石頭守護者。周遭全化為灰，唯牠堅硬得燒不毀。", "道路的石头守护者。周遭全化为灰，唯它坚硬得烧不毁。"],
    "boss.ash_dragon.name": ["Dragão de Cinza", "Ash Dragon", "Dragón de Ceniza", "Aschedrache", "Dragon de cendre", "Пепельный дракон", "Naga Abu", "灰の竜", "잿빛 용", "灰燼龍", "灰烬龙"],
    "boss.ash_dragon.line": ["Sou o que restou do fogo dele.", "I am what remains of his fire.", "Soy lo que quedó de su fuego.", "Ich bin, was von seinem Feuer blieb.", "Je suis ce qui reste de son feu.", "Я — то, что осталось от его огня.", "Akulah sisa apinya.", "我はあの方の火の残りだ。", "나는 그분의 불이 남긴 것이다.", "我是他火焰的殘餘。", "我是他火焰的残余。"],
    "boss.ash_dragon.lore": ["Quando Kuroe apagou a lanterna, a chama não sumiu: caiu na terra e virou dragão.", "When Kuroe put out his lantern, the flame did not vanish: it fell to the earth and became a dragon.", "Cuando Kuroe apagó su linterna, la llama no desapareció: cayó a la tierra y se volvió dragón.", "Als Kuroe seine Laterne löschte, verschwand die Flamme nicht: Sie fiel zur Erde und wurde ein Drache.", "Quand Kuroe a éteint sa lanterne, la flamme n'a pas disparu : elle est tombée et devenue dragon.", "Когда Куроэ погасил фонарь, пламя не исчезло: упало на землю и стало драконом.", "Saat Kuroe memadamkan lenteranya, apinya tak lenyap: jatuh ke tanah dan menjadi naga.", "黒衛が灯籠を消した時、炎は消えなかった。地に落ち、竜となった。", "쿠로에가 등불을 껐을 때 불꽃은 사라지지 않았다. 땅에 떨어져 용이 되었다.", "黑衛熄滅燈籠時，火焰並未消失：它落入大地化為龍。", "黑卫熄灭灯笼时，火焰并未消失：它落入大地化为龙。"],
    "boss.red_oni.name": ["Oni Vermelho", "Red Oni", "Oni Rojo", "Roter Oni", "Oni rouge", "Красный они", "Oni Merah", "赤鬼", "붉은 오니", "赤鬼", "赤鬼"],
    "boss.red_oni.line": ["O Senhor espera. Eu não.", "The Lord waits. I don't.", "El Señor espera. Yo no.", "Der Herr wartet. Ich nicht.", "Le Seigneur attend. Pas moi.", "Владыка ждёт. Я — нет.", "Sang Penguasa menunggu. Aku tidak.", "主は待つ。俺は待たん。", "주인님은 기다린다. 난 아니다.", "主人會等。我不會。", "主人会等。我不会。"],
    "boss.red_oni.lore": ["O guarda do portão do Yomi. Serve Kuroe, mas nunca entendeu por que ele ainda carrega um brinquedo.", "The guard of Yomi's gate. It serves Kuroe but never understood why he still carries a toy.", "El guardia de la Puerta del Yomi. Sirve a Kuroe, pero nunca entendió por qué aún lleva un juguete.", "Der Wächter am Tor von Yomi. Er dient Kuroe, verstand aber nie, warum dieser noch ein Spielzeug trägt.", "Le garde de la porte du Yomi. Il sert Kuroe sans comprendre pourquoi celui-ci garde un jouet.", "Страж врат Ёми. Служит Куроэ, но так и не понял, зачем тот носит игрушку.", "Penjaga Gerbang Yomi. Ia melayani Kuroe, tapi tak pernah paham mengapa tuannya masih membawa mainan.", "黄泉の門の番人。黒衛に仕えるが、なぜ主が今もおもちゃを持つのか分からない。", "황천의 문지기. 쿠로에를 섬기지만, 그가 왜 아직 장난감을 지니는지 이해하지 못했다.", "黃泉之門的守衛。侍奉黑衛，卻始終不懂他為何仍帶著玩具。", "黄泉之门的守卫。侍奉黑卫，却始终不懂他为何仍带着玩具。"],
    "boss.kuroe.name": ["Kuroe, Senhor da Procissão", "Kuroe, Lord of the Procession", "Kuroe, Señor de la Procesión", "Kuroe, Herr der Prozession", "Kuroe, seigneur de la Procession", "Куроэ, Владыка шествия", "Kuroe, Penguasa Arak-arakan", "百鬼の主・黒衛", "행렬의 주인 쿠로에", "百鬼之主・黑衛", "百鬼之主・黑卫"],
    "boss.kuroe.line": ["Finalmente. Vem, ninguém mais vai te tocar.", "At last. Come, no one will touch you again.", "Por fin. Ven, nadie volverá a tocarte.", "Endlich. Komm, niemand wird dich je wieder berühren.", "Enfin. Viens, plus personne ne te touchera.", "Наконец. Пойдём, тебя больше никто не тронет.", "Akhirnya. Ayo, tak ada lagi yang akan menyentuhmu.", "ようやくだ。来い、もう誰にも触れさせない。", "마침내. 오너라, 이제 아무도 너를 건드리지 못한다.", "終於。來吧，再也沒人能碰妳。", "终于。来吧，再也没人能碰你。"],
    "boss.kuroe.lore": ["Apagou a própria luz para que outra continuasse acesa. A Ordem chamou isso de traição.", "He put out his own light so another could stay lit. The Order called it treason.", "Apagó su propia luz para que otra siguiera encendida. La Orden lo llamó traición.", "Er löschte sein eigenes Licht, damit ein anderes brennen konnte. Der Orden nannte es Verrat.", "Il a éteint sa propre lumière pour qu'une autre reste allumée. L'Ordre a appelé cela trahison.", "Он погасил свой свет, чтобы другой продолжал гореть. Орден назвал это предательством.", "Ia memadamkan cahayanya sendiri agar cahaya lain tetap menyala. Ordo menyebutnya pengkhianatan.", "別の灯を守るため、自らの光を消した。教団はそれを裏切りと呼んだ。", "다른 빛이 꺼지지 않도록 자신의 빛을 껐다. 결사는 그것을 배신이라 불렀다.", "他熄滅自己的光，讓另一盞得以長明。教團稱之為背叛。", "他熄灭自己的光，让另一盏得以长明。教团称之为背叛。"],
    "boss.kuroe.phase1": ["Venha, a procissão inteira vai te levar para casa!", "Come, the whole procession will carry you home!", "¡Ven, toda la procesión te llevará a casa!", "Komm, die ganze Prozession bringt dich heim!", "Viens, toute la procession va te ramener !", "Идём, всё шествие отнесёт тебя домой!", "Ayo, seluruh arak-arakan akan membawamu pulang!", "来い、行列すべてでお前を連れて帰る！", "오너라, 행렬 전체가 너를 집으로 데려가리라!", "來吧，整個百鬼都會帶妳回家！", "来吧，整个百鬼都会带你回家！"],
    "boss.kuroe.phase2": ["Apague essa luz. Ela só te machuca.", "Put out that light. It only hurts you.", "Apaga esa luz. Solo te hace daño.", "Lösch dieses Licht. Es tut dir nur weh.", "Éteins cette lumière. Elle ne fait que te blesser.", "Погаси этот свет. Он лишь ранит тебя.", "Padamkan cahaya itu. Ia hanya menyakitimu.", "その光を消せ。お前を傷つけるだけだ。", "그 빛을 꺼라. 너를 아프게 할 뿐이다.", "熄掉那道光。它只會傷害妳。", "熄掉那道光。它只会伤害你。"],
    "boss.shinigami.name": ["Shinigami", "Shinigami", "Shinigami", "Shinigami", "Shinigami", "Синигами", "Shinigami", "死神", "사신", "死神", "死神"],
    "boss.shinigami.line": ["O amanhecer era o seu prazo.", "Dawn was your deadline.", "El amanecer era tu plazo.", "Der Morgen war deine Frist.", "L'aube était ton échéance.", "Рассвет был твоим сроком.", "Fajar adalah batas waktumu.", "夜明けがお前の期限だった。", "새벽이 너의 기한이었다.", "黎明是你的期限。", "黎明是你的期限。"],
    "boss.shinigami.lore": ["Vem buscar quem desafia a ordem natural e fica na noite depois do amanhecer.", "It comes for those who defy the natural order and stay in the night after dawn.", "Viene por quienes desafían el orden natural y siguen en la noche tras el amanecer.", "Er holt jene, die der natürlichen Ordnung trotzen und nach dem Morgen in der Nacht bleiben.", "Il vient chercher ceux qui défient l'ordre naturel et restent dans la nuit après l'aube.", "Приходит за теми, кто бросает вызов порядку вещей и остаётся в ночи после рассвета.", "Ia datang menjemput yang menantang tatanan alam dan tetap di malam setelah fajar.", "自然の理に背き、夜明け後も夜に留まる者を迎えに来る。", "자연의 이치를 거스르고 새벽 뒤에도 밤에 머무는 자를 데리러 온다.", "前來帶走違抗自然秩序、黎明後仍留在夜裡的人。", "前来带走违抗自然秩序、黎明后仍留在夜里的人。"],
    "boss.izanami.name": ["Izanami", "Izanami", "Izanami", "Izanami", "Izanami", "Идзанами", "Izanami", "伊邪那美", "이자나미", "伊邪那美", "伊邪那美"],
    "boss.izanami.line": ["Toda luz um dia desce até mim.", "Every light comes down to me one day.", "Toda luz algún día desciende hasta mí.", "Jedes Licht sinkt eines Tages zu mir herab.", "Toute lumière finit un jour par descendre jusqu'à moi.", "Всякий свет однажды нисходит ко мне.", "Setiap cahaya suatu hari turun kepadaku.", "どんな光も、いつか我がもとへ降りてくる。", "모든 빛은 언젠가 내게로 내려온다.", "所有的光終有一天會降到我身邊。", "所有的光终有一天会降到我身边。"],
    "boss.izanami.lore": ["A deusa que governa o Yomi. A procissão é o lamento dela: a cada cem anos, tenta puxar o mundo dos vivos para perto de si.", "The goddess who rules Yomi. The procession is her lament: every hundred years she tries to draw the living world close.", "La diosa que gobierna el Yomi. La procesión es su lamento: cada cien años intenta atraer el mundo de los vivos.", "Die Göttin, die über Yomi herrscht. Die Prozession ist ihre Klage: Alle hundert Jahre will sie die Welt der Lebenden zu sich ziehen.", "La déesse qui règne sur le Yomi. La procession est sa complainte : tous les cent ans, elle tente d'attirer le monde des vivants.", "Богиня, правящая Ёми. Шествие — её плач: каждые сто лет она пытается притянуть мир живых.", "Dewi penguasa Yomi. Arak-arakan adalah ratapannya: tiap seratus tahun ia mencoba menarik dunia orang hidup.", "黄泉を治める女神。行列は彼女の嘆き。百年ごとに生者の世を引き寄せようとする。", "황천을 다스리는 여신. 행렬은 그녀의 비탄이다. 백 년마다 산 자의 세상을 끌어당기려 한다.", "統治黃泉的女神。百鬼是她的哀歌：每隔百年，她都想把生者之世拉近身旁。", "统治黄泉的女神。百鬼是她的哀歌：每隔百年，她都想把生者之世拉近身旁。"],
    "boss.izanami.phase1": ["Os vivos me abandonaram. Eu não os abandono.", "The living abandoned me. I do not abandon them.", "Los vivos me abandonaron. Yo no los abandono.", "Die Lebenden verließen mich. Ich verlasse sie nicht.", "Les vivants m'ont abandonnée. Moi, je ne les abandonne pas.", "Живые покинули меня. Я их не покину.", "Yang hidup meninggalkanku. Aku tak meninggalkan mereka.", "生者は我を捨てた。我は彼らを捨てぬ。", "산 자는 나를 버렸다. 나는 그들을 버리지 않는다.", "生者拋棄了我。我不會拋棄他們。", "生者抛弃了我。我不会抛弃他们。"],
}
